aufgaben.sysml:
// in Anforderungen
requirement <'R-008'> rampenfahrfaehigkeit {
    doc /* Das FTF befährt Rampen mit einer Steigung von höchstens 4 % mit voller Last. */
}

// in Verknuepfungen
satisfy Anforderungen::rampenfahrfaehigkeit by Physik::ftf.fahrwerk;

// in Anforderungen
requirement <'R-008'> fahrgeschwindigkeitPersonenverkehr {
    doc /* In Bereichen mit Personenverkehr darf das FTF höchstens 0,8 m/s fahren. */
}

// in Verknuepfungen
satisfy Anforderungen::fahrgeschwindigkeitPersonenverkehr by Physik::ftf.fahrwerk;

// in Anforderungen
requirement <'R-008'> fahrzeugbreite {
    doc /* Die Fahrzeugbreite darf 900 mm nicht überschreiten. */
}

// in Verknuepfungen
satisfy Anforderungen::fahrzeugbreite by Physik::ftf;

// in Anforderungen
requirement <'R-008'> ladestandSchwelle {
    doc /* Bei einem Ladestand unter 15 % nimmt das FTF keine neuen Fahraufträge an. */
}

// in Verknuepfungen
satisfy Anforderungen::ladestandSchwelle by Physik::ftf.akku;

// in Anforderungen
requirement <'R-008'> statusmelderhythmus {
    doc /* Das FTF meldet Position, Ladestand und Störungen mindestens einmal pro Sekunde an das Leitsystem. */
}

// in Verknuepfungen
satisfy Anforderungen::statusmelderhythmus by Physik::ftf.funk;

// in Anforderungen
requirement <'R-008'> verbindungsverlustReaktion {
    doc /* Bei Verbindungsverlust von mehr als 5 Sekunden hält das FTF kontrolliert an. */
}

// in Verknuepfungen
satisfy Anforderungen::verbindungsverlustReaktion by Physik::ftf.funk;

// in Anforderungen
requirement <'R-008'> hubhoehe {
    doc /* Die Lastaufnahme hebt Ladungsträger um bis zu 120 mm an. */
}

// in Verknuepfungen
satisfy Anforderungen::hubhoehe by Physik::ftf.hubwerk;

// in Anforderungen
requirement <'R-008'> zweischichtbetrieb {
    doc /* Das FTF ist für einen Zweischichtbetrieb ausgelegt, bei dem zwischen den Schichten 30 Minuten zum Laden zur Verfügung stehen. */
}

// in Verknuepfungen
satisfy Anforderungen::zweischichtbetrieb by Physik::ftf.akku;

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Bei niedrigem Ladestand zur Ladestation navigieren und dort ankommen. */
}

// in Verknuepfungen
allocate Funktionen::ladestationAnfahren to Physik::ftf.rechner;

// in Anforderungen
requirement <'R-008'> warnsignal {
    doc /* Das FTF warnt vor dem Anfahren und bei Richtungswechseln akustisch und optisch. */
}

// in Funktionen
action <'F-008'> warnsignalAusloesen {
    doc /* Akustische und optische Warnsignale vor dem Anfahren und bei Richtungswechseln auslösen. */
}

// in Verknuepfungen
satisfy Anforderungen::warnsignal by Physik::ftf.sicherheitssteuerung;
allocate Funktionen::warnsignalAusloesen to Physik::ftf.sicherheitssteuerung;

// in Funktionen
action <'F-008'> stoerungenMelden {
    doc /* Störungen des Fahrzeugs an das Leitsystem melden. */
}

// in Verknuepfungen
allocate Funktionen::stoerungenMelden to Physik::ftf.funk;

// in Anforderungen
requirement <'R-008'> schutzfeldHinten {
    doc /* Bei Rückwärtsfahrt wird das Schutzfeld hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::Sicherheitslaserscanner;

// in Verknuepfungen
satisfy Anforderungen::schutzfeldHinten by Physik::ftf.scannerHinten;

// in Logik
part def <'L-009'> Warnleuchte {
    doc /* Optisches Warnsignal zur Ankündigung von Anfahren und Richtungswechsel. */
}

// in Physik::ftf
part <'P-009'> warnleuchte : Logik::Warnleuchte;

// in Logik
part def <'L-009'> Ladespule {
    doc /* Spule für das kontaktlose Laden des Energiespeichers. */
}

// in Physik::ftf
part <'P-009'> ladespule : Logik::Ladespule;

// in Logik
part def <'L-009'> NotHaltTaster {
    doc /* Mechanischer Taster zur manuellen Auslösung des Not-Halts. */
}

// in Physik::ftf
part <'P-009'> notHaltTasterRechts : Logik::NotHaltTaster;

// in Funktionen
action <'F-008'> hindernisseHintenErkennen {
    doc /* Hindernisse im hinteren Schutzfeld erkennen. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::Sicherheitslaserscanner;

// in Verknuepfungen
allocate Funktionen::hindernisseHintenErkennen to Physik::ftf.scannerHinten;
